<?php $layoutTitle='Reports'; require __DIR__.'/layout-top.php'; $from=$_GET['from']??date('Y-01-01'); $to=$_GET['to']??date('Y-m-d'); $st=db()->prepare("SELECT c.crop_name,COUNT(h.harvest_id) harvest_count,COALESCE(SUM(h.quantity_kg),0) total_kg,COALESCE(AVG(h.quantity_kg),0) avg_kg,COALESCE(SUM(h.quantity_kg*h.selling_price_per_kg),0) gross_value FROM harvest h JOIN planting p ON p.planting_id=h.planting_id JOIN crop c ON c.crop_id=p.crop_id WHERE h.harvest_date BETWEEN ? AND ? GROUP BY c.crop_id,c.crop_name ORDER BY total_kg DESC"); $st->execute([$from,$to]); $rows=$st->fetchAll(); ?><section class="section"><div class="container"><p class="eyebrow">ANALYSIS</p><h1 class="title is-3">Agricultural reports</h1><div class="box"><form class="field is-grouped is-align-items-flex-end"><input type="hidden" name="page" value="reports"><div class="control"><label class="label">From</label><input class="input" type="date" name="from" value="<?=e($from)?>"></div><div class="control"><label class="label">To</label><input class="input" type="date" name="to" value="<?=e($to)?>"></div><div class="control"><button class="button is-primary">Apply period</button></div><div class="control"><button type="button" class="button is-light" onclick="window.print()">Print report</button></div></form><div class="table-container"><table class="table is-fullwidth is-striped"><thead><tr><th>Crop</th><th>Harvests</th><th>Total yield (kg)</th><th>Average (kg)</th><th>Gross value</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['crop_name'])?></td><td><?=e($r['harvest_count'])?></td><td><?=number_format((float)$r['total_kg'],2)?></td><td><?=number_format((float)$r['avg_kg'],2)?></td><td><?=number_format((float)$r['gross_value'],2)?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="has-text-grey">No harvests in this date range.</td></tr><?php endif ?></tbody></table></div><p class="help">Gross value is computed from recorded quantity and price per kilogram.</p></div></div></section><?php require __DIR__.'/layout-bottom.php'; ?>